def rule(id,dim,src,trigger,method,passed,fail,fix,evidence,priority='高',state='待實作／待驗證'):
 rows.append(dict(規格ID=id,驗收面向=dim,適用來源=src,觸發與適用條件=trigger,檢查方法=method,通過條件=passed,失敗或未知判定=fail,處理與重下載原則=fix,必留證據=evidence,優先序=priority,目前證據狀態=state))
